            empresa: empresa.nombre,
            // 👇 AQUÍ PROTEGEMOS A ANGULAR CONTRA ERRORES
            empresaId: empresa.id ? empresa.id.substring(0, 8).toUpperCase() : "SIN-ID",
            ruc: empresa.ruc,
